        /// <summary>"Sprinter_PC_C", "/Game/.../Sprinter_PC.Default__Sprinter_PC_C" or "Sprinter" -> developer name.</summary>
        public static string DeveloperNameFromClass(string agentClass)
        {
            if (string.IsNullOrEmpty(agentClass)) return "";
            string s = agentClass;
            int dot = s.LastIndexOf('.');
            if (dot >= 0) s = s.Substring(dot + 1);
            if (s.StartsWith("Default__", StringComparison.Ordinal)) s = s.Substring(9);
            if (s.EndsWith("_PC_C", StringComparison.OrdinalIgnoreCase)) s = s.Substring(0, s.Length - 5);
            return s;
        }

